  const S_XML_DECL_NAME = 2; // <?xml foo
  const S_XML_DECL_EQ = 3; // <?xml foo=
  const S_XML_DECL_VALUE_START = 4; // <?xml foo=
  const S_XML_DECL_VALUE = 5; // <?xml foo="bar"
  
