  const CR = 0xD;
  const SPACE = 0x20;
  const BANG = 0x21;
  const DQUOTE = 0x22;
  const HASH = 0x23;
  const AMP = 0x26;
  const SQUOTE = 0x27;
  const MINUS = 0x2D;
